CREATE TABLE `usuarios` (
  `USid` int(11) NOT NULL AUTO_INCREMENT,
  `USnombre` varchar(100) NOT NULL,
  `USapellidos` varchar(150) NOT NULL,
  `UScorreo` varchar(255) NOT NULL,
  `UScontrasena` varchar(255) NOT NULL,
  `UStelefono` varchar(30) DEFAULT NULL,
  `USdireccion` varchar(255) DEFAULT NULL,
  `UScreadoen` datetime DEFAULT current_timestamp(),
  `USactualizadoen` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `RUid` int(11) DEFAULT NULL,
  `usrol` varchar(20) NOT NULL,
  `USreset_token` varchar(120) DEFAULT NULL,
  `USreset_token_expira` datetime DEFAULT NULL,
  PRIMARY KEY (`USid`),
  UNIQUE KEY `UScorreo` (`UScorreo`),
  KEY `fk_usuarios_rol` (`RUid`),
  CONSTRAINT `fk_usuarios_rol` FOREIGN KEY (`RUid`) REFERENCES `rolusuarios` (`RUid`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
